import {assignLevel,ensureLevels,isPast,archiveLevel} from './levels.js';
import {policy} from './rewards.js';
import {parsePack,validatePack} from './packs.js';
import {history,report,validateBackup,conceptMastered,exportBackup,importBackup} from './store.js';
import {PROFILES,THEMES} from './model.js';
export const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function download(name,value){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
export function parentUI(api){
 const {getData,save,screen,on,home,practice}=api,$=id=>document.getElementById(id);let draft=null,originalId=null,levelTarget='ari';
 const note=text=>{$('parent-note').textContent=text;};
 function settings(){const data=getData();screen(`<section class="panel wide"><p class="eyebrow">GROWN-UPS’ WORKSHOP</p><h2>Parent Settings</h2><p>Choose a world and any study pack. New subjects use the same runner.</p><div class="form-grid">${['ari','kal'].map(id=>{const p=data.profiles[id];return `<section class="editor-section"><h3>${PROFILES[id].name}</h3><label>Active study pack<select id="${id}-pack">${Object.values(data.packs).map(pack=>`<option value="${esc(pack.id)}" ${p.activePack===pack.id?'selected':''}>${esc(pack.title)}${pack.archived?' (archived)':''}</option>`).join('')}</select></label><label>Adventure world<select id="${id}-theme">${Object.entries(THEMES).map(([key,t])=>`<option value="${key}" ${key===p.theme?'selected':''}>${t.name}</option>`).join('')}</select></label><div class="form-grid"><label>Lanes (3–8)<input id="${id}-lanes" type="number" min="3" max="8" value="${p.settings.lanes}"></label><label>Speed (7–26)<input id="${id}-speed" type="number" min="7" max="26" value="${p.settings.speed}"></label></div><label>Successful groups per question (2–20)<input id="${id}-interval" type="number" min="2" max="20" value="${p.settings.interval}"></label><div class="row"><button data-settings="${id}">SAVE SETTINGS</button><button data-report="${id}">PROGRESS</button><button data-level-manage="${id}">TESTS & LEVELS</button><button data-homework-manage="${id}">READING HOMEWORK</button></div></section>`;}).join('')}</div><p class="subtle">Settings apply to new adventures. Continue keeps that adventure’s settings. Guest saves stay on this device. Explorer accounts show their cloud sync status; export a private backup before switching or restoring data.</p><div class="row"><label>Assign new imports and new tests to<select id="new-level-target">${Object.entries(PROFILES).map(([id,p])=>`<option value="${id}">${p.name}</option>`).join('')}</select></label><button class="primary" id="manage">MANAGE STUDY PACKS</button><button id="backup">EXPORT ALL PROGRESS</button><button id="restore">RESTORE BACKUP</button><input id="backup-input" type="file" accept="application/json,.json" hidden><button class="quiet" id="home">BACK TO ARCADE</button></div><p id="parent-note" role="status" class="error"></p></section>`,'parent');
  document.querySelectorAll('[data-settings]').forEach(b=>b.onclick=()=>{const id=b.dataset.settings,p=data.profiles[id];const lanes=Number($(id+'-lanes').value),speed=Number($(id+'-speed').value),interval=Number($(id+'-interval').value);if(!Number.isInteger(lanes)||lanes<3||lanes>8||!Number.isFinite(speed)||speed<7||speed>26||!Number.isInteger(interval)||interval<2||interval>20){note('Use lanes 3–8, speed 7–26, and checkpoint interval 2–20.');return;}assignLevel(data,id,$(id+'-pack').value,true);p.theme=$(id+'-theme').value;p.settings={lanes,speed,interval};history(data,id,p.activePack);save();note(PROFILES[id].name+' settings saved.');});
  document.querySelectorAll('[data-report]').forEach(b=>b.onclick=()=>dashboard(b.dataset.report));document.querySelectorAll('[data-level-manage]').forEach(b=>b.onclick=()=>levelManager(b.dataset.levelManage));document.querySelectorAll('[data-homework-manage]').forEach(b=>b.onclick=()=>api.homework?.(b.dataset.homeworkManage));on('manage',()=>{levelTarget=$('new-level-target').value;list();});on('home',home);on('backup',()=>download('crystal-quest-backup.json',exportBackup(data)));on('restore',()=>$('backup-input').click());on('backup-input',async()=>{try{const file=$('backup-input').files[0];if(!file)return;const text=await file.text();if(text.length>5000000)throw Error('Backup is too large.');const parsed=JSON.parse(text);const restored=importBackup(parsed);if(!confirm('Replace both runner profiles and custom packs with this backup? Original platform-game saves are kept.'))return;api.replaceData(restored);save();settings();note('Backup restored.');}catch(e){note(e.message);}},'change');
 }
 function levelManager(id){levelTarget=id;const data=getData(),p=data.profiles[id];ensureLevels(p);const cfg=policy(p);screen(`<section class="panel wide"><p class="eyebrow">${PROFILES[id].name} • TESTS & LEVELS</p><h2>Current and past tests</h2><p>Assigning a new current test keeps every older level, pet, wallet and learning record. No previous completion is required.</p><label>Assign an existing study pack<select id="assign-level">${Object.values(data.packs).map(pack=>`<option value="${esc(pack.id)}">${esc(pack.title)}</option>`).join('')}</select></label><button id="assign-current">SELECT CURRENT TEST</button><div class="pack-list">${p.levels.map(l=>{const pack=data.packs[l.packId];return `<section class="editor-section"><h3>Level ${l.number}: ${esc(pack.title)}</h3><p>${isPast(p,pack)?`PAST / ARCHIVED · ${Math.round(cfg.pastCrystals*100)}% crystals · ${Math.round(cfg.pastXP*100)}% XP`:'CURRENT · Normal rewards'}</p><div class="row"><button data-current="${esc(pack.id)}">REACTIVATE / MAKE CURRENT</button><button data-archive-level="${esc(pack.id)}">ARCHIVE TEST</button><button data-edit-level="${esc(pack.id)}">EDIT STUDY MATERIAL</button><button data-learning="${esc(pack.id)}">VIEW LEARNING PROGRESS</button><button data-export-level="${esc(pack.id)}">EXPORT JSON</button></div></section>`;}).join('')}</div><details><summary>Reward limits and rates</summary><div class="form-grid">${[['pastCrystals','Past crystal rate (0–1)'],['pastXP','Past pet XP rate (0–1)'],['replayBonus','Completed current-test bonus rate (0–1)'],['dailyCrystals','Daily crystal cap'],['dailyXP','Daily pet XP cap'],['minimum','Minimum milestone reward (default 0)']].map(([key,label])=>`<label>${label}<input id="rate-${key}" type="number" step="${key.startsWith('daily')||key==='minimum'?'1':'.05'}" min="0" value="${cfg[key]}"></label>`).join('')}</div><button id="save-rates">SAVE REWARD SETTINGS</button></details><div class="row"><button id="add-level" class="primary">ADD NEW TEST / LEVEL</button><button id="import-level">IMPORT STUDY PACK JSON</button><button id="back">PARENT SETTINGS</button><button id="home">ARCADE</button></div><p id="parent-note" role="status"></p></section>`,'parent');on('back',settings);on('home',home);on('assign-current',()=>{assignLevel(data,id,$('assign-level').value,true);save();levelManager(id);});on('add-level',()=>edit(null));on('import-level',list);document.querySelectorAll('[data-current]').forEach(b=>b.onclick=()=>{assignLevel(data,id,b.dataset.current,true);save();levelManager(id);});document.querySelectorAll('[data-archive-level]').forEach(b=>b.onclick=()=>{if(!archiveLevel(p,b.dataset.archiveLevel,data.packs)){note('Assign another test before archiving the only current level.');return;}save();levelManager(id);});document.querySelectorAll('[data-edit-level]').forEach(b=>b.onclick=()=>edit(b.dataset.editLevel));document.querySelectorAll('[data-learning]').forEach(b=>b.onclick=()=>dashboard(id,b.dataset.learning));document.querySelectorAll('[data-export-level]').forEach(b=>b.onclick=()=>download(b.dataset.exportLevel+'.json',data.packs[b.dataset.exportLevel]));on('save-rates',()=>{const cfg=Object.fromEntries(['pastCrystals','pastXP','replayBonus','dailyCrystals','dailyXP','minimum'].map(k=>[k,Number($('rate-'+k).value)]));if(![cfg.pastCrystals,cfg.pastXP,cfg.replayBonus].every(n=>Number.isFinite(n)&&n>=0&&n<=1)||![cfg.dailyCrystals,cfg.dailyXP,cfg.minimum].every(n=>Number.isSafeInteger(n)&&n>=0&&n<=100000)){note('Use rates 0–1 and whole-number limits 0–100000.');return;}p.rewardPolicy=cfg;save();note('Reward settings saved. Learning scores are unchanged.');});}
 function dashboard(id,selected){const data=getData(),p=data.profiles[id],pack=data.packs[selected||p.activePack],h=history(data,id,pack.id),s=report(pack,h);screen(`<section class="panel wide"><p class="eyebrow">${PROFILES[id].name} • LEARNING JOURNAL</p><h2>${esc(pack.title)}</h2><label>Review another pack<select id="report-pack">${Object.values(data.packs).map(x=>`<option value="${esc(x.id)}" ${pack.id===x.id?'selected':''}>${esc(x.title)}${x.archived?' (archived)':''}</option>`).join('')}</select></label><div class="stats">${[[s.attempted,'Questions assessed'],[s.never,'Never encountered'],[s.presented?Math.round(100*s.first/s.presented)+'%':'—','First-attempt accuracy'],[`${s.mastered}/${s.total}`,'Concepts mastered'],[s.needs,'Need practice'],[h.sessions||0,'Pack sessions']].map(([n,label])=>`<div class="stat"><strong>${n}</strong>${label}</div>`).join('')}</div><p>Latest session: ${h.lastSession?esc(new Date(h.lastSession).toLocaleString()):'Not yet'}. Gameplay crystals: ${p.crystals}. High score: ${p.highScore}.</p><p class="subtle">A retry never becomes a first-try success. Mastery requires a fresh first-try success on every question linked to that concept, with no outstanding mistakes. Unseen variants remain unassessed. Big crystal totals do not award study mastery.</p><div class="table-wrap"><table id="progress-table"><thead><tr><th>Question / concept</th><th>Presented</th><th>First try</th><th>Wrong attempts</th><th>Later correct</th><th>Latest / review</th></tr></thead><tbody>${pack.questions.map(q=>{const r=h.questions[q.id];return `<tr><td>${esc(q.prompt)}<small>${esc(q.concepts.join(', '))}</small></td><td>${r?.presented||0}</td><td>${r?.firstCorrect||0}</td><td>${r?.incorrect||0}</td><td>${r?.laterCorrect||0}</td><td>${esc(r?.latest||'Never encountered')}${r?.review?' • PRACTICE':''}<small>${r?.lastDate?esc(new Date(r.lastDate).toLocaleDateString()):''}</small></td></tr>`;}).join('')}</tbody></table></div><details><summary>All ${s.total} required concepts</summary><div class="table-wrap"><table><tbody>${[...pack.vocabulary,...pack.facts].map(c=>`<tr><td>${esc(c.term||c.definition)}${c.term?'<small>'+esc(c.definition)+'</small>':''}</td><td>${conceptMastered(pack,h,c.id)?'Mastered':h.concepts[c.id]?.presented?'Still learning':'Unassessed'}</td></tr>`).join('')}</tbody></table></div></details><div class="row"><button class="primary" id="review">PRACTICE MISSED QUESTIONS</button><button id="back">PARENT SETTINGS</button><button class="quiet" id="reset">RESET THIS PACK’S PROGRESS</button><button class="quiet" id="home">ARCADE</button></div></section>`,'parent');on('report-pack',()=>dashboard(id,$('report-pack').value),'change');on('review',()=>practice(id,pack.id,true));on('back',settings);on('home',home);on('reset',()=>{if(confirm('Clear only '+PROFILES[id].name+' learning and runner progress for '+pack.title+'?')){delete p.learning[pack.id];delete p.runs[pack.id];for(const key of Object.keys(p.courses||{}))if(p.courses[key].packId===pack.id)delete p.courses[key];save();dashboard(id,pack.id);}});}
 function list(){const data=getData();screen(`<section class="panel wide"><p class="eyebrow">STUDY-PACK LIBRARY</p><h2>New tests. Same adventure.</h2><p>New tests and imports are assigned to ${PROFILES[levelTarget].name}. Existing level numbers and histories stay unchanged.</p><p>Add material here, or import a study-pack JSON file. Archived packs and their results stay available. <a href="./runner/example-pack.json" download>Example pack</a> · <a href="./runner/study-pack.schema.json" download>JSON schema</a></p><div class="pack-list">${Object.values(data.packs).map(p=>`<button data-edit="${esc(p.id)}"><span>${esc(p.title)}<small>${esc(p.subject)} • ${p.questions.length} questions ${p.archived?'• ARCHIVED':''}</small></span><span>EDIT ➜</span></button>`).join('')}</div><div class="row"><button class="primary" id="new-pack">NEW STUDY PACK</button><button id="import-pack">IMPORT JSON</button><input id="pack-input" type="file" accept="application/json,.json" hidden><button id="back">PARENT SETTINGS</button></div><p id="parent-note" role="status" class="error"></p></section>`,'parent');document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>edit(b.dataset.edit));on('new-pack',()=>edit(null));on('back',settings);on('import-pack',()=>$('pack-input').click());on('pack-input',async()=>{try{const file=$('pack-input').files[0];if(!file)return;const pack=parsePack(await file.text());if(data.packs[pack.id]&&!confirm('Replace the existing '+pack.title+' pack? Learning history is kept.'))return;data.packs[pack.id]=pack;assignLevel(data,levelTarget,pack.id,true);save();list();note('Pack imported: '+pack.title);}catch(e){note(e.message);}},'change');}
 function collect(){draft.id=$('pack-id').value.trim();draft.title=$('pack-title').value.trim();draft.subject=$('pack-subject').value.trim();draft.grade=$('pack-grade').value.trim();draft.vocabulary=$('vocab-rows').value.split('\n').filter(x=>x.trim()).map(line=>{const [id,term,...definition]=line.split('|').map(x=>x.trim());return {id,term,definition:definition.join(' | ')};});draft.facts=$('fact-rows').value.split('\n').filter(x=>x.trim()).map(line=>{const [id,...definition]=line.split('|').map(x=>x.trim());return {id,definition:definition.join(' | ')};});}
 function edit(id,qid=null,retain=false){if(!retain){originalId=id;draft=id?structuredClone(getData().packs[id]):{version:1,id:'new-test-'+Date.now().toString(36),title:'My new test',subject:'Science',grade:'Custom',vocabulary:[],facts:[],questions:[]};}const q=draft.questions.find(q=>q.id===qid);screen(`<section class="panel wide"><p class="eyebrow">MANUAL STUDY-PACK EDITOR</p><h2>${esc(draft.title)}</h2><div class="form-grid"><label>Unique pack ID<input id="pack-id" value="${esc(draft.id)}" ${originalId?'readonly':''}></label><label>Title<input id="pack-title" value="${esc(draft.title)}"></label><label>Subject<input id="pack-subject" value="${esc(draft.subject)}"></label><label>Grade / difficulty<input id="pack-grade" value="${esc(draft.grade)}"></label></div><div class="editor-section"><h3>Vocabulary and facts</h3><p class="subtle">One entry per line. Every concept ID needs a question below.</p><label>Vocabulary: id | word | original definition<textarea id="vocab-rows" placeholder="addition | ADDITION | Putting numbers together.">${esc(draft.vocabulary.map(c=>[c.id,c.term,c.definition].join(' | ')).join('\n'))}</textarea></label><label>Facts: id | fact<textarea id="fact-rows" placeholder="sum-five | Two plus three equals five.">${esc(draft.facts.map(c=>[c.id,c.definition].join(' | ')).join('\n'))}</textarea></label></div><div class="editor-section"><h3>Questions (${draft.questions.length})</h3><label>Edit a question<select id="question-select"><option value="">New question</option>${draft.questions.map(x=>`<option value="${esc(x.id)}" ${x.id===qid?'selected':''}>${esc(x.prompt)}</option>`).join('')}</select></label><div class="form-grid"><label>Question ID<input id="question-id" value="${esc(q?.id||'question-'+(draft.questions.length+1))}"></label><label>Concept IDs (comma separated)<input id="concept-ids" value="${esc(q?.concepts.join(',')||'')}"></label></div><label>Prompt<input id="prompt" value="${esc(q?.prompt||'')}"></label><label>Question type<select id="question-type">${['choice','matching','picture','order'].map(type=>`<option ${q?.type===type?'selected':''}>${type}</option>`).join('')}</select></label><label>Choices (2–4): one label per line; optional picture after |<textarea id="choice-lines" placeholder="Five | star&#10;Four | earth&#10;Six | moon">${esc(q?.choices.map(c=>c.label+(c.picture?' | '+c.picture:'')).join('\n')||'')}</textarea></label><p class="subtle">Built-in pictures include earth, sun, moon, full, new, sphere, dipper, north, rise, set, star, spin, orbit. Use plain labels for any subject.</p><label>Correct choice number (ordering: numbers in correct sequence, such as 2,1,3)<input id="correct-choice" value="${q?esc(q.type==='order'?q.answer.map(a=>q.choices.findIndex(c=>c.id===a)+1).join(','):q.choices.findIndex(c=>c.id===q.answer)+1):'1'}"></label><label>Hint<input id="hint" value="${esc(q?.hint||'')}"></label><label>Explanation<input id="explanation" value="${esc(q?.explanation||'')}"></label><div class="row"><button id="save-question" class="secondary">ADD / UPDATE QUESTION</button>${qid?'<button id="delete-question" class="danger">DELETE QUESTION</button>':''}</div></div><p id="parent-note" role="status" class="error"></p><div class="row"><button id="save-pack" class="primary">SAVE STUDY PACK</button><button id="export-pack">EXPORT JSON</button>${originalId?'<button id="archive">'+(draft.archived?'RESTORE FROM ARCHIVE':'ARCHIVE PACK')+'</button><button id="delete-pack" class="danger">DELETE PACK</button>':''}<button id="back">BACK TO LIBRARY</button></div></section>`,'parent');
  on('question-select',()=>{collect();edit(originalId,$('question-select').value,true);},'change');on('save-question',()=>{collect();const lines=$('choice-lines').value.split('\n').filter(x=>x.trim());const choices=lines.map((s,i)=>{const [label,picture]=s.split('|').map(x=>x.trim());return {id:'c'+(i+1),label,...(picture?{picture}:{})};});const type=$('question-type').value,nums=$('correct-choice').value.split(',').map(n=>Number(n.trim())-1);const next={id:$('question-id').value.trim(),concepts:$('concept-ids').value.split(',').map(x=>x.trim()).filter(Boolean),type,prompt:$('prompt').value.trim(),choices,answer:type==='order'?nums.map(i=>choices[i]?.id):choices[nums[0]]?.id,hint:$('hint').value.trim(),explanation:$('explanation').value.trim()};const copy=structuredClone(draft);copy.questions=copy.questions.filter(x=>x.id!==(qid||next.id));copy.questions.push(next);const errors=validatePack(copy).filter(e=>!e.startsWith('Concept '));if(errors.length){note(errors.join('\n'));return;}draft=copy;edit(originalId,next.id,true);note('Question added to this draft. Tap SAVE STUDY PACK to keep it.');});on('delete-question',()=>{collect();draft.questions=draft.questions.filter(q=>q.id!==qid);edit(originalId,null,true);});
  const checked=()=>{collect();const errors=validatePack(draft);if(errors.length){note(errors.join('\n'));return false;}return true;};on('save-pack',()=>{if(!checked())return;const data=getData();if(draft.id!==originalId&&data.packs[draft.id]){note('That pack ID already exists. Use a different ID.');return;}data.packs[draft.id]=structuredClone(draft);if(!originalId)assignLevel(data,levelTarget,draft.id,true);save();originalId=draft.id;edit(originalId,qid);note('Study pack saved. Select it for either player in Parent Settings.');});on('export-pack',()=>{if(checked())download(draft.id+'.json',draft);});on('back',list);on('archive',()=>{if(!draft.archived){const data=getData(),affected=Object.values(data.profiles).filter(p=>p.activePack===originalId);for(const p of affected){ensureLevels(p);if(!p.levels.some(l=>l.packId!==originalId&&!l.archived&&!data.packs[l.packId]?.archived)){note('Assign another current test before archiving this level.');return;}}for(const p of affected)archiveLevel(p,originalId,data.packs);}draft.archived=!draft.archived;getData().packs[originalId]={...getData().packs[originalId],archived:draft.archived};save();list();});on('delete-pack',()=>{const data=getData();if(Object.values(data.profiles).some(p=>p.activePack===originalId||p.learning[originalId]||p.runs[originalId]||p.levels?.some(l=>l.packId===originalId)||Object.values(p.courses||{}).some(r=>r.packId===originalId))){note('This pack has active settings or saved learning. Archive it to keep those records.');return;}if(confirm('Delete this unused study pack?')){delete data.packs[originalId];save();list();}});
 }
 return {settings,dashboard,list,levelManager};
}
